-- Daycare Ceria - aplikasi penitipan anak. Skema database MySQL / MariaDB
-- Impor lewat phpMyAdmin (tab Import) atau: mysql -u root < database/daycare.sql
CREATE DATABASE IF NOT EXISTS daycare CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE daycare;
SET NAMES utf8mb4;
SET time_zone = '+07:00';

DROP TABLE IF EXISTS tagihan, catatan, kehadiran, titip_jemput, penjemput, anak, ortu, menu, pengaturan, pengguna, batas_coba;

CREATE TABLE pengguna (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(40) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','operator') NOT NULL DEFAULT 'operator',
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pengaturan (kunci VARCHAR(40) PRIMARY KEY, nilai TEXT) ENGINE=InnoDB;

-- Orang tua masuk ke portal dengan nomor HP + PIN 6 angka (disimpan sebagai hash)
CREATE TABLE ortu (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  hp VARCHAR(20) NOT NULL UNIQUE,
  pin VARCHAR(255) NOT NULL,
  alamat VARCHAR(200) NOT NULL DEFAULT '',
  aktif TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE anak (
  id INT AUTO_INCREMENT PRIMARY KEY,
  ortu_id INT NOT NULL,
  nama VARCHAR(100) NOT NULL,
  panggilan VARCHAR(30) NOT NULL,
  jk ENUM('L','P') NOT NULL,
  tgl_lahir DATE NOT NULL,
  kelompok ENUM('bayi','batita','balita') NOT NULL,
  paket ENUM('bulanan','harian') NOT NULL DEFAULT 'bulanan',
  alergi VARCHAR(200) NOT NULL DEFAULT '',
  catatan_kesehatan VARCHAR(255) NOT NULL DEFAULT '',
  aktif TINYINT(1) NOT NULL DEFAULT 1,
  FOREIGN KEY (ortu_id) REFERENCES ortu(id) ON DELETE RESTRICT
) ENGINE=InnoDB;

-- Selain orang tua, hanya penjemput terdaftar (atau titipan hari itu) yang boleh menjemput
CREATE TABLE penjemput (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anak_id INT NOT NULL,
  nama VARCHAR(100) NOT NULL,
  hubungan VARCHAR(40) NOT NULL,
  hp VARCHAR(20) NOT NULL DEFAULT '',
  FOREIGN KEY (anak_id) REFERENCES anak(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE titip_jemput (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anak_id INT NOT NULL,
  tanggal DATE NOT NULL,
  nama VARCHAR(100) NOT NULL,
  hubungan VARCHAR(40) NOT NULL,
  dibuat_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (anak_id) REFERENCES anak(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE kehadiran (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anak_id INT NOT NULL,
  tanggal DATE NOT NULL,
  status ENUM('hadir','izin','sakit') NOT NULL DEFAULT 'hadir',
  masuk TIME NULL,
  pulang TIME NULL,
  diantar VARCHAR(100) NOT NULL DEFAULT '',
  dijemput VARCHAR(100) NOT NULL DEFAULT '',
  suhu DECIMAL(3,1) NULL,
  denda INT NOT NULL DEFAULT 0,
  keterangan VARCHAR(255) NOT NULL DEFAULT '',
  UNIQUE KEY (anak_id, tanggal),
  INDEX (tanggal),
  FOREIGN KEY (anak_id) REFERENCES anak(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Catatan harian: makan, susu, tidur, toilet, mood, aktivitas, obat
CREATE TABLE catatan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anak_id INT NOT NULL,
  tanggal DATE NOT NULL,
  waktu TIME NOT NULL,
  jenis VARCHAR(15) NOT NULL,
  nilai VARCHAR(30) NOT NULL DEFAULT '',
  detail VARCHAR(255) NOT NULL DEFAULT '',
  selesai TIME NULL,                  -- jam bangun untuk catatan tidur
  user_id INT NULL,
  INDEX (anak_id, tanggal),
  FOREIGN KEY (anak_id) REFERENCES anak(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES pengguna(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE tagihan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anak_id INT NOT NULL,
  bulan CHAR(7) NOT NULL,             -- 2026-11
  paket ENUM('bulanan','harian') NOT NULL,
  hari_hadir INT NOT NULL DEFAULT 0,
  biaya INT NOT NULL DEFAULT 0,
  denda INT NOT NULL DEFAULT 0,
  total INT NOT NULL DEFAULT 0,
  status ENUM('belum','lunas') NOT NULL DEFAULT 'belum',
  metode VARCHAR(20) NOT NULL DEFAULT '',
  dibayar_at DATETIME NULL,
  UNIQUE KEY (anak_id, bulan),
  FOREIGN KEY (anak_id) REFERENCES anak(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE menu (
  hari TINYINT PRIMARY KEY,           -- 1 Senin ... 5 Jumat
  pagi VARCHAR(120) NOT NULL DEFAULT '',
  siang VARCHAR(120) NOT NULL DEFAULT '',
  sore VARCHAR(120) NOT NULL DEFAULT ''
) ENGINE=InnoDB;

CREATE TABLE batas_coba (kunci VARCHAR(80) PRIMARY KEY, n INT NOT NULL DEFAULT 0, mulai DATETIME NOT NULL) ENGINE=InnoDB;


