-- Hanya hari kerja; untuk hari ini hanya yang jamnya sudah lewat saat impor (anak yang belum dijemput tetap tampil di daycare)
INSERT INTO kehadiran (anak_id, tanggal, status, masuk, pulang, diantar, dijemput, suhu, denda, keterangan)
SELECT anak_id, CURDATE() - INTERVAL n DAY, status, masuk,
       IF(n = 0 AND pulang > CURTIME(), NULL, pulang), diantar, IF(n = 0 AND pulang > CURTIME(), '', dijemput), suhu,
       IF(n = 0 AND pulang > CURTIME(), 0, denda), ket
FROM h WHERE WEEKDAY(CURDATE() - INTERVAL n DAY) < 5 AND (n > 0 OR status <> 'hadir' OR masuk <= CURTIME());
INSERT INTO catatan (anak_id, tanggal, waktu, jenis, nilai, detail, selesai, user_id)
SELECT c.anak_id, CURDATE() - INTERVAL c.n DAY, c.waktu, c.jenis, c.nilai, c.detail, IF(c.n = 0 AND c.selesai > CURTIME(), NULL, c.selesai), c.user_id
FROM c JOIN kehadiran k ON k.anak_id = c.anak_id AND k.tanggal = CURDATE() - INTERVAL c.n DAY AND k.status = 'hadir'
WHERE c.n > 0 OR (c.waktu <= CURTIME() AND (k.pulang IS NULL OR c.waktu <= k.pulang));

-- Tagihan bulan lalu (sebagian besar sudah lunas)
INSERT INTO tagihan (anak_id, bulan, paket, hari_hadir, biaya, denda, total, status, metode, dibayar_at)
SELECT a.id, DATE_FORMAT(CURDATE() - INTERVAL 1 MONTH, '%Y-%m'), a.paket, COUNT(k.id),
       IF(a.paket = 'bulanan', 1500000, COUNT(k.id) * 85000), COALESCE(SUM(k.denda), 0),
       IF(a.paket = 'bulanan', 1500000, COUNT(k.id) * 85000) + COALESCE(SUM(k.denda), 0),
       IF(a.id IN (4, 11), 'belum', 'lunas'), IF(a.id IN (4, 11), '', IF(a.id % 3 = 0, 'tunai', 'transfer')),
       IF(a.id IN (4, 11), NULL, LAST_DAY(CURDATE() - INTERVAL 1 MONTH) + INTERVAL (a.id % 5) DAY + INTERVAL 10 HOUR)
FROM anak a LEFT JOIN kehadiran k ON k.anak_id = a.id AND k.status = 'hadir' AND DATE_FORMAT(k.tanggal, '%Y-%m') = DATE_FORMAT(CURDATE() - INTERVAL 1 MONTH, '%Y-%m')
GROUP BY a.id;

-- Isi catatan makan mengikuti menu hari itu
UPDATE catatan c JOIN menu m ON m.hari = WEEKDAY(c.tanggal) + 1
SET c.detail = CASE WHEN c.detail LIKE 'Snack pagi%' THEN CONCAT('Snack pagi: ', m.pagi)
                    WHEN c.detail LIKE 'Makan siang%' THEN CONCAT('Makan siang: ', m.siang)
                    ELSE CONCAT('Snack sore: ', m.sore) END
WHERE c.jenis = 'makan';

